fr, en = {}, {}
for key, lf, hf, le, he, vf, ve in T:
    fr[P + key] = lf
    fr[P + key + '.hint'] = hf
    en[P + key] = le
    en[P + key + '.hint'] = he
    if vf:
        assert len(vf) == len(ve), key
        for i, v in enumerate(vf):
            fr[P + key + '.' + str(i)] = v
            en[P + key + '.' + str(i)] = ve[i]
for key, f, e in OTHER:
    fr['crusadecraft.urban.' + key] = f
    en['crusadecraft.urban.' + key] = e

here = os.path.dirname(os.path.abspath(__file__))
for name, data in (('p60_fr.json', fr), ('p60_en.json', en)):
    with io.open(os.path.join(here, name), 'w', encoding='utf-8', newline='\n') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write('\n')
print(len(fr), 'textes')
